int orientation(long long ax, long long ay, long long bx, long long by, long long cx, long long cy) {
    long long v = (bx - ax) * (cy - ay) - (by - ay) * (cx - ax);
    if (v > 0) return 1;    // counter-clockwise, left turn
    if (v < 0) return -1;   // clockwise, right turn
    return 0;               // collinear
}

