function orientation(a, b, c) {
  const v = (b[0]-a[0]) * (c[1]-a[1]) - (b[1]-a[1]) * (c[0]-a[0]);
  if (v > 0) return 1;    // counter-clockwise, left turn
  if (v < 0) return -1;   // clockwise, right turn
  return 0;               // collinear
}
